return {["scripts/actions/spells/trust/maat_uc.lua"]={["Path"]="scripts/actions/spells/trust/maat_uc.lua",["SHA256"]="28b5af0c144c53f79aa93e0cd658408e1e52e7ae458757954f4b619391fa1588",["Text"]="-----------------------------------\n-- Trust: Maat UC\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.MAAT)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n    -- TODO test and incorporate (possesses increased kick attacks rate)\n    mob:addGambit(ai.t.SELF, { ai.c.HPP_LT, 50 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.CHAKRA })\n    mob:addGambit(ai.t.SELF, { ai.c.HAS_TOP_ENMITY, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.COUNTERSTANCE })\n    mob:addGambit(ai.t.SELF, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.IMPETUS })\n\n    if mob:getMaster():getMainLvl() >= 50 then\n        -- TODO no current implementation to have multiple criterias on setTrustTOSkillSetting to allow opening a skill chain and closing a skill chain\n        mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.HIGHEST, 3000)\n    end\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/makki-chebukki.lua"]={["Path"]="scripts/actions/spells/trust/makki-chebukki.lua",["SHA256"]="9e54a0202adbc53d2e7c2d38d9655a927ec1f9c069421c493ad86f491221bf2b",["Text"]="-----------------------------------\n-- Trust: Makki-Chebukki\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/margret.lua"]={["Path"]="scripts/actions/spells/trust/margret.lua",["SHA256"]="bf743c96e35a6f30eb2d3fccfff81fbc190f9cb4a7a61beaedb46f0ec7821266",["Text"]="-----------------------------------\n-- Trust: Margret\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/matsui-p.lua"]={["Path"]="scripts/actions/spells/trust/matsui-p.lua",["SHA256"]="50ce3806205676040e2fbd9a7b311864d459f172b11fba8e7449710c6669bed8",["Text"]="-----------------------------------\n-- Trust: Matsui-P\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/maximilian.lua"]={["Path"]="scripts/actions/spells/trust/maximilian.lua",["SHA256"]="eba194d687c9254746c60b3dfc87aa9360436e1f0f04a21630e0060041af100c",["Text"]="-----------------------------------\n-- Trust: Maximilian\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/mayakov.lua"]={["Path"]="scripts/actions/spells/trust/mayakov.lua",["SHA256"]="9663aa57c784d9818d1d9ced8ac8bc188ad7a7bcf3425101d3adeefc942e32a0",["Text"]="-----------------------------------\n-- Trust: Mayakov\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/mihli_aliapoh.lua"]={["Path"]="scripts/actions/spells/trust/mihli_aliapoh.lua",["SHA256"]="6ba756753a5b3d62c0196401f24a6a2c92b14dc249cfd998cd08e7021a04083c",["Text"]="-----------------------------------\n-- Trust: Mihli Aliapoh\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    -- Records of Eminence: Alter Ego: Mihli Aliapoh\n    if caster:getEminenceProgress(934) then\n        xi.roe.onRecordTrigger(caster, 934)\n    end\n\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.RUGHADJEEN] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.GADALAR] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.NAJELITH] = xi.trust.messageOffset.TEAMWORK_3,\n        [xi.magic.spell.ZAZARG] = xi.trust.messageOffset.TEAMWORK_4,\n    })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 25 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_II }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE })\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.AFFLATUS_SOLACE }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.AFFLATUS_SOLACE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 75 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.PROTECT }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PROTECTRA })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.SHELL }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SHELLRA })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.POISON }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.POISONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PARALYSIS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PARALYNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.BLINDNESS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.BLINDNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SILENCE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.SILENA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PETRIFICATION }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.DISEASE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.VIRUNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.CURSE_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURSNA })\n\n    mob:addGambit(ai.t.SELF, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.PARALYSIS }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PARALYZE }, 60)\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.SLOW }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SLOW }, 60)\n\n    mob:addListener('WEAPONSKILL_USE', 'MIHLI_ALIAPOH_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == 3203 then -- Scouring Bubbles\n        -- Bah! Guess I'll pull out another one of my trrricks!\n            if math.randomInt(1, 100) <= 33 then\n                xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n            end\n        end\n    end)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/mildaurion.lua"]={["Path"]="scripts/actions/spells/trust/mildaurion.lua",["SHA256"]="05824c0fdc577f8394f0ba9d75c6fd186891260184da7e8e5696764684c4e3a5",["Text"]="-----------------------------------\n-- Trust: Mildaurion\n-- https://ffxiclopedia.fandom.com/wiki/Trust:_Mildaurion\n-- https://www.bg-wiki.com/ffxi/Cipher:_Mildaurion\n-- From wikis:\n-- \"Tries to open skillchains when the player reaches 1500 TP. Does not try to open skillchains with other trusts.\"\n-- \"Will close skillchains with players and other trusts if possible, otherwise uses a weapon skill at 3000 TP.\"\n-- TODO: We don't have a combination of OPENER and CLOSER for TP skill settings, so leaving as OPENER for now.\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.PRISHE] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.ULMIA] = xi.trust.messageOffset.TEAMWORK_2,\n    })\n\n    mob:addListener('WEAPONSKILL_USE', 'MILDAURION_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == xi.mobSkill.LIGHT_BLADE_3 then\n            --  For Vana'diel!\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\n\n    mob:addMod(xi.mod.MPP, 100)\n\n    mob:setTrustTPSkillSettings(ai.tp.OPENER, ai.s.RANDOM)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/mnejing.lua"]={["Path"]="scripts/actions/spells/trust/mnejing.lua",["SHA256"]="81764b3aecf93cceae7470926e858fe1f4319ad47088aba4de420857a36d3d5b",["Text"]="-----------------------------------\n-- Trust: Mnejing\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:setMobMod(xi.mobMod.CAN_SHIELD_BLOCK, 1)\n    mob:setMobMod(xi.mobMod.CAN_PARRY, 3)\n\n    mob:setMod(xi.mod.SHIELD_MASTERY_TP, 40)\n    mob:setMod(xi.mod.SHIELDBLOCKRATE, 45)\n    mob:addMod(xi.mod.ENMITY, 15)\n    mob:addMod(xi.mod.DMG, -375) -- Passive -37.5% Damage Taken Reduction.\n    mob:addMod(xi.mod.HPP, 20)\n\n    local lastSynergyBonus = 0\n\n    mob:addListener('COMBAT_TICK', 'MNEJING_CTICK', function(mobArg)\n        local targetBonus = 0\n        local party = mobArg:getMaster():getPartyWithTrusts()\n\n        for _, member in pairs(party) do\n            if member:getObjType() == xi.objType.TRUST then\n                if member:getTrustID() == xi.magic.spell.NASHMEIRA then\n                    targetBonus = 10\n                end\n            end\n        end\n\n        if targetBonus ~= lastSynergyBonus then\n            mobArg:delMod(xi.mod.DEF, lastSynergyBonus)\n            mobArg:delMod(xi.mod.ENMITY, lastSynergyBonus)\n            mobArg:addMod(xi.mod.DEF, targetBonus)\n            mobArg:addMod(xi.mod.ENMITY, targetBonus)\n\n            lastSynergyBonus = targetBonus\n        end\n    end)\n\n    mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS,      0                        }, { ai.r.MS, ai.s.SPECIFIC, xi.mobSkill.PROVOKE_AUTOMATON     }, 30)\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS,  xi.effect.FLASH          }, { ai.r.MS, ai.s.SPECIFIC, xi.mobSkill.FLASHBULB_AUTOMATON   }, 45)\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_MS, 0                        }, { ai.r.MS, ai.s.SPECIFIC, xi.mobSkill.SHIELD_BASH_AUTOMATON }, 30)\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_WS, 0                        }, { ai.r.MS, ai.s.SPECIFIC, xi.mobSkill.SHIELD_BASH_AUTOMATON }, 30)\n    mob:addGambit(ai.t.TARGET, { ai.c.STATUS_FLAG, xi.effectFlag.DISPELABLE }, { ai.r.MS, ai.s.SPECIFIC, xi.mobSkill.DISRUPTOR_AUTOMATON   }, 15)\n\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.RANDOM, 1500)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/monberaux.lua"]={["Path"]="scripts/actions/spells/trust/monberaux.lua",["SHA256"]="ab5b4b516e19662ce415f21c57ae3938ddebbdccfb93be8f08e3f0785dba6db4",["Text"]="-----------------------------------\n-- Trust: Monberaux\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    -- TODO: Find right animation for Mix: Insomniant.\n    -- TODO: Add PLD/RUN traits like Resist Sleep and Tenacity.\n    -- TODO: Add Cover ability with proper conditions (stand behind Monberaux when you have top enmity)\n    local finalElixir = mob:getMaster():getCharVar('finalElixir') -- CVar used to store Elixir donation info.\n    local potAoe      = mob:getMaster():getCharVar('monbAoe')     -- CVar used to store gil donation info.\n\n    if potAoe == 0 then\n        if finalElixir == 0 then\n            xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n        elseif finalElixir == 1 then\n            xi.trust.message(mob, xi.trust.messageOffset.TEAMWORK_1) -- 1 Elixir\n        else\n            xi.trust.message(mob, xi.trust.messageOffset.TEAMWORK_2) -- 2 Elixir\n        end\n    else\n        if finalElixir == 0 then\n            xi.trust.message(mob, xi.trust.messageOffset.TEAMWORK_3) -- Gil donation (AoE)\n        elseif finalElixir == 1 then\n            xi.trust.message(mob, xi.trust.messageOffset.TEAMWORK_4) -- 1 Elixir and Gil\n        else\n            xi.trust.message(mob, xi.trust.messageOffset.TEAMWORK_5) -- ALL Donations\n        end\n    end\n\n    local healingMoveCooldown = math.randomInt(3, 4) -- Mix I Retail values from BGWiki\n    local buffMoveCooldown    = 60 -- Mix II Retail values from BGWiki\n    local mpMoveCooldown      = 90 -- Mix III Retail values from BGWiki\n\n    -- MobMods\n    mob:setMod(xi.mod.MPP, -90)\n    mob:setMod(xi.mod.SLEEPRES, 100)   -- Handle negate sleep\n    mob:setMod(xi.mod.LULLABYRES, 100) -- Handle negate sleep\n    mob:setMod(xi.mod.STATUSRES, 15)\n\n    -- Guard Drink should always be the first spell he casts\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.PROTECT }, { ai.r.MS, ai.s.SPECIFIC, 4255 }, healingMoveCooldown) -- Mix: Guard Drink (Prot/Shell)\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.SHELL   }, { ai.r.MS, ai.s.SPECIFIC, 4255 }, healingMoveCooldown) -- Mix: Guard Drink (Prot/Shell)\n\n    -- Handle his Final Elixir (item donation) system, will use whenever a party memeber is asleep\n    if finalElixir ~= 0 then\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_I }, { ai.r.MS, ai.s.SPECIFIC, 4231 }, healingMoveCooldown)\n    end\n\n    -- Top Priority Heals\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 40 }, { ai.r.MS, ai.s.SPECIFIC, 4237 }, healingMoveCooldown) -- Mix: Max Potion (700 HP)\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 55 }, { ai.r.MS, ai.s.SPECIFIC, 4236 }, healingMoveCooldown) -- Max Potion (500 HP)\n\n    -- Mix I Single Target\n    if potAoe == 0 then\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS,      xi.effect.BLINDNESS       }, { ai.r.MS, ai.s.SPECIFIC, 4248 }, healingMoveCooldown) -- Mix: Eye Drops\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS,      xi.effect.POISON          }, { ai.r.MS, ai.s.SPECIFIC, 4246 }, healingMoveCooldown) -- Mix: Antidote\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS,      xi.effect.SILENCE         }, { ai.r.MS, ai.s.SPECIFIC, 4249 }, healingMoveCooldown) -- Echo Drops\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS,      xi.effect.PARALYSIS       }, { ai.r.MS, ai.s.SPECIFIC, 4247 }, healingMoveCooldown) -- Mix: Para-B-Gone\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE    }, { ai.r.MS, ai.s.SPECIFIC, 4253 }, healingMoveCooldown) -- Mix: Panacea-1\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS,      xi.effect.PLAGUE          }, { ai.r.MS, ai.s.SPECIFIC, 4251 }, healingMoveCooldown) -- Vaccine\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS,      xi.effect.PETRIFICATION   }, { ai.r.MS, ai.s.SPECIFIC, 4252 }, healingMoveCooldown) -- Mix: Gold Needle\n        mob:addGambit(ai.t.PARTY, {\n            ai.l.OR({ ai.c.STATUS, xi.effect.CURSE_I }, { ai.c.STATUS, xi.effect.CURSE_II }, { ai.c.STATUS, xi.effect.BANE }, { ai.c.STATUS, xi.effect.DOOM })\n        }, { ai.r.MS, ai.s.SPECIFIC, 4242 }, healingMoveCooldown) -- Holy Water\n\n    -- Mix I AoE\n    else\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS,      xi.effect.BLINDNESS     }, { ai.r.MS, ai.s.SPECIFIC, 4240 }, healingMoveCooldown) -- AoE Mix: Eye Drops\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS,      xi.effect.POISON        }, { ai.r.MS, ai.s.SPECIFIC, 4238 }, healingMoveCooldown) -- AoE Mix: Antidote\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS,      xi.effect.SILENCE       }, { ai.r.MS, ai.s.SPECIFIC, 4241 }, healingMoveCooldown) -- AoE Echo Drops\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS,      xi.effect.PARALYSIS     }, { ai.r.MS, ai.s.SPECIFIC, 4239 }, healingMoveCooldown) -- AoE Mix: Para-B-Gone\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE  }, { ai.r.MS, ai.s.SPECIFIC, 4245 }, healingMoveCooldown) -- AoE Mix: Panacea-1\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS,      xi.effect.PLAGUE        }, { ai.r.MS, ai.s.SPECIFIC, 4243 }, healingMoveCooldown) -- AoE Mix: Vaccine\n        mob:addGambit(ai.t.PARTY, { ai.c.STATUS,      xi.effect.PETRIFICATION }, { ai.r.MS, ai.s.SPECIFIC, 4244 }, healingMoveCooldown) -- AoE Mix: Gold Needle\n        mob:addGambit(ai.t.PARTY, {\n            ai.l.OR({ ai.c.STATUS, xi.effect.CURSE_I }, { ai.c.STATUS, xi.effect.CURSE_II }, { ai.c.STATUS, xi.effect.BANE }, { ai.c.STATUS, xi.effect.DOOM })\n        }, { ai.r.MS, ai.s.SPECIFIC, 4242 }, healingMoveCooldown)   -- AoE Holy Water\n    end\n\n    -- Mix II\n    -- mob:addGambit(ai.t.PARTY,  { ai.c.NOT_STATUS, xi.effect.NEGATE_SLEEP    }, { ai.r.MS, ai.s.SPECIFIC, 4256 }, healingMoveCooldown) -- Insomniant. Disabled because animation when used is completely wrong.\n    mob:addGambit(ai.t.PARTY,  { ai.c.NOT_STATUS, xi.effect.REGEN           }, { ai.r.MS, ai.s.SPECIFIC, 4257 }, buffMoveCooldown) -- Mix: Life Water\n    mob:addGambit(ai.t.PARTY,  { ai.c.NOT_STATUS, xi.effect.STR_BOOST       }, { ai.r.MS, ai.s.SPECIFIC, 4261 }, buffMoveCooldown) -- Mix: Samson's Strength\n    mob:addGambit(ai.t.PARTY,  { ai.c.NOT_STATUS, xi.effect.MAGIC_DEF_BOOST }, { ai.r.MS, ai.s.SPECIFIC, 4259 }, buffMoveCooldown) -- Mix: Dragon Shield\n    mob:addGambit(ai.t.CASTER, { ai.c.NOT_STATUS, xi.effect.MAGIC_ATK_BOOST }, { ai.r.MS, ai.s.SPECIFIC, 4258 }, buffMoveCooldown) -- Mix: Elemental Power\n    mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS,                             0 }, { ai.r.MS, ai.s.SPECIFIC, 4260 }, buffMoveCooldown) -- Dark Potion (666 Dark Damage)\n\n    -- Mix III\n    mob:addGambit(ai.t.CASTER, { ai.c.MPP_LT, 50 }, { ai.r.MS, ai.s.SPECIFIC, 4254 }, mpMoveCooldown) -- Mix: Dry Ether Concoction\n\n    -- Less Priority Heals\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 65 }, { ai.r.MS, ai.s.SPECIFIC, 4235 }, healingMoveCooldown) -- Hyper Potion (250 HP)\n    -- mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 75 }, { ai.r.MS, ai.s.SPECIFIC, 4234 }, healingMoveCooldown) -- X-Potion (150 HP) -- Disabled to prevent super spam\n    -- mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 85 }, { ai.r.MS, ai.s.SPECIFIC, 4232 }, healingMoveCooldown) -- Potion (50 HP)    -- Disabled to prevent super spam\n\n    -- Listener to handle removal of CharVar that handles elixir donation --\n    mob:addListener('WEAPONSKILL_USE', 'MONBERAUX_WEAPONSKILL_USE', function(mobArg, targetArg, skill, tp, action)\n        if skill:getID() == xi.mobSkill.MIX_FINAL_ELIXIR then\n            local master = mobArg:getMaster()\n            if master then\n                master:setCharVar('finalElixir', master:getCharVar('finalElixir') - 1)\n            end\n        end\n    end)\n\n    --Listener to SPECIAL_MOVE -- DISABLED needs correct coding for table\n    --mob:addListener('WEAPONSKILL_BEFORE_USE', 'MONBERAUX_WEAPONSKILL_BEFORE_USE', function(mobArg, skillid)\n    --local buffs = { 4234, 4239, 4240, 4241, 4242, 4243, 4244, 4245, 4246, 4247, 4248, 4248, 4249, 4250, 4251, 4252 } -- status condition removals only\n    --if skillid == 4259 then\n    --xi.trust.message(mob, xi.trust.messageOffset.SPECIAL_MOVE_1) -- Using Mix: Dragon Shield: Illness and unjury know no boundaries!\n    --elseif skillid == buffs then\n    --xi.trust.message(mob, xi.trust.messageOffset.SPECIAL_MOVE_2) -- Other: I shall administer a remedy immediately!\n    --end\n    --end)\n\n    mob:setAutoAttackEnabled(false)\n\n    -- No TP for Monberaux\n    mob:addListener('COMBAT_TICK', 'MONBERAUX_CTICK', function(mobArg)\n        mobArg:setTP(0)\n    end)\n\n    -- This listener is needed for Monberaux to display the correct skill name in the combat log.\n    mob:addListener('WEAPONSKILL_USE', 'MONBERAUX_WS', function(mobArg, targetArg, skill, tp, action)\n        action:setCategory(xi.action.category.MOBABILITY_FINISH)\n    end)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NO_MOVE)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/moogle.lua"]={["Path"]="scripts/actions/spells/trust/moogle.lua",["SHA256"]="5d03a1def5580ae5ae7c8d3c0af57221c09b825388db64779daf4ad8df2b7ab6",["Text"]="-----------------------------------\n-- Trust: Moogle\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.FABLINIX] = xi.trust.messageOffset.TEAMWORK_1,\n    })\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NON_COMBAT)\n\n    mob:addMod(xi.mod.AURA_SIZE, 600) -- Trust have a 12 yalm aura 6 base + 6 from mod\n\n    local effectParams =\n    {\n        power = 6,\n        origin = mob,\n        tick = 3,\n        subType = xi.effect.TRUST_AURA_REFRESH,\n        subPower = mob:getMainLvl(),\n        subIcon = xi.effect.GEO_REFRESH,\n        tier = xi.auraTarget.ALLIES,\n        flag = xi.effectFlag.AURA\n    }\n\n    mob:addStatusEffect(xi.effect.COLURE_ACTIVE, effectParams)\n\n    mob:addGambit(ai.t.SELF, { { ai.c.TIMER, 5 }, { ai.c.RANDOM, 45 } }, { ai.r.ANIM_STRING, ai.s.RANDOM_ANIMATION, 5 })\n\n    mob:setAutoAttackEnabled(false)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/morimar.lua"]={["Path"]="scripts/actions/spells/trust/morimar.lua",["SHA256"]="2ee4423aa17f435ec789bb8a2d23349f7a685f67f710d1707915e172f8e0c59c",["Text"]="-----------------------------------\n-- Trust: Morimar\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/mumor.lua"]={["Path"]="scripts/actions/spells/trust/mumor.lua",["SHA256"]="362affe3b597fd0b93e35990953cd030e58a0c387c9955b01c8b175971f69176",["Text"]="-----------------------------------\n-- Trust: Mumor\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\n-- Define the main jobs with access to primary healing used to toggle Samba type\nlocal healingJobs =\n{\n    xi.job.WHM,\n    xi.job.RDM,\n    xi.job.SCH,\n    xi.job.PLD,\n}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.MUMOR_II)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.UKA_TOTLIHN] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.ULLEGORE   ] = xi.trust.messageOffset.TEAMWORK_2,\n    })\n\n    -- Dynamic modifier that checks party member list on tick to apply\n    mob:addListener('COMBAT_TICK', 'MUMOR_CTICK', function(mobArg)\n        local sambaDurationBoost = 0\n        local party = mobArg:getMaster():getPartyWithTrusts()\n        for _, member in pairs(party) do\n            if member:getObjType() == xi.objType.TRUST then\n                if\n                    member:getTrustID() == xi.magic.spell.UKA_TOTLIHN\n                then\n                    sambaDurationBoost = 10\n                end\n            end\n        end\n\n        -- Always set the boost, even if Uka wasn't found.\n        -- This accounts for her being in the party and giving the boost\n        -- and also if she dies and the boost goes away.\n        mobArg:setMod(xi.mod.SAMBA_DURATION, sambaDurationBoost)\n    end)\n\n    -- Sets stance\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.SABER_DANCE }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SABER_DANCE })\n\n    -- Step usage: -DEF debuff and stuns\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.WEAKENED_DAZE_5 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.STUTTER_STEP })\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_WS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.VIOLENT_FLOURISH })\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_MS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.VIOLENT_FLOURISH })\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_JA, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.VIOLENT_FLOURISH })\n    mob:addGambit(ai.t.TARGET, { ai.c.CASTING_MA, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.VIOLENT_FLOURISH })\n\n    -- Samba logic\n    -- Checks masters job, adjusts samba type if master has a healer main job.\n    for i = 1, #healingJobs do\n        local master  = mob:getMaster()\n        if\n            master and\n            master:getMainJob() == healingJobs[i]\n        then\n            mob:addGambit(ai.t.SELF, { ai.c.NO_SAMBA, ai.r.JA }, { 0, ai.s.SPECIFIC, xi.ja.HASTE_SAMBA })\n        end\n    end\n\n    -- Adds ecosystem to adjust samba to haste if target is undead\n    mob:addGambit(ai.t.TARGET, { ai.c.IS_ECOSYSTEM, xi.ecosystem.UNDEAD }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.HASTE_SAMBA })\n    -- Else picks highest drain spell available\n    mob:addGambit(ai.t.SELF, { ai.c.NO_SAMBA, 0 }, { ai.r.JA, ai.s.BEST_SAMBA, xi.ja.DRAIN_SAMBA })\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/mumor_ii.lua"]={["Path"]="scripts/actions/spells/trust/mumor_ii.lua",["SHA256"]="ac4919667d86a318ac7ab2f5402c37af1483058d9e2a6349515fe3b677628462",["Text"]="-----------------------------------\n-- Trust: Mumor II\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.MUMOR)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/naja_salaheem.lua"]={["Path"]="scripts/actions/spells/trust/naja_salaheem.lua",["SHA256"]="ad98fcf9cb1e33653ae30c91e1cf6038f973ca32527f428ab500d9138f8bc9cd",["Text"]="-----------------------------------\n-- Trust: Naja Salaheem\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.NAJA_UC)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.GESSHO] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.RONGELOUTS] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.ABQUHBAH] = xi.trust.messageOffset.TEAMWORK_3,\n    })\n\n    mob:setTrustTPSkillSettings(ai.tp.ASAP, ai.s.RANDOM)\n\n    mob:addListener('WEAPONSKILL_USE', 'NAJA_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == 3215 then -- Peacebreaker\n            --  Cha-ching! Thirty gold coins!\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\n\n    mob:addGambit(ai.t.SELF, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.FOCUS })\n\n    mob:addGambit(ai.t.SELF, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.DODGE })\n\n    mob:addGambit(ai.t.SELF, { ai.c.HAS_TOP_ENMITY, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.COUNTERSTANCE })\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/naja_uc.lua"]={["Path"]="scripts/actions/spells/trust/naja_uc.lua",["SHA256"]="6965c7c63f84f4f50303f49f3c9ee27c8341db7d8bef0f86a91d51bf3168c1d5",["Text"]="-----------------------------------\n-- Trust: Naja Salaheem UC\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.NAJA_SALAHEEM)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/najelith.lua"]={["Path"]="scripts/actions/spells/trust/najelith.lua",["SHA256"]="8dc06936e2fa24c88cd57ea1cded9017924595efc9bd6cda96685970c561bfb4",["Text"]="-----------------------------------\n-- Trust: Najelith\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/naji.lua"]={["Path"]="scripts/actions/spells/trust/naji.lua",["SHA256"]="f68631820225a678e584d00a2387a2a1bb1240516f71e7a6d7a0b752b92ba68f",["Text"]="-----------------------------------\n-- Trust: Naji\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local bastokFirstTrust = caster:getCharVar('Quest[1][92]Prog')\n    local zone = caster:getZoneID()\n\n    if\n        bastokFirstTrust == 1 and\n        (zone == xi.zone.NORTH_GUSTABERG or zone == xi.zone.SOUTH_GUSTABERG)\n    then\n        caster:setCharVar('Quest[1][92]Prog', 2)\n    end\n\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.AYAME] = xi.trust.messageOffset.TEAMWORK_1,\n    })\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_HAS_TOP_ENMITY, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PROVOKE })\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/nanaa_mihgo.lua"]={["Path"]="scripts/actions/spells/trust/nanaa_mihgo.lua",["SHA256"]="83fb36a526d13cb424471a78bb12e6fac98c741cf1413a3f63dab7f92b57d7e0",["Text"]="-----------------------------------\n-- Trust: Nanaa Mihgo\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.ROMAA_MIHGO] = xi.trust.messageOffset.TEAMWORK_1,\n    })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.DESPOIL })\n\n    mob:setTrustTPSkillSettings(ai.tp.OPENER, ai.s.HIGHEST)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/nashmeira.lua"]={["Path"]="scripts/actions/spells/trust/nashmeira.lua",["SHA256"]="3e1528687f00f633ef511e31101be638f9703c17c3ca1bffeebc69a00043f4e7",["Text"]="-----------------------------------\n-- Trust: Nashmeira\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.NASHMEIRA_II)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/nashmeira_ii.lua"]={["Path"]="scripts/actions/spells/trust/nashmeira_ii.lua",["SHA256"]="1fa86da34d14de9ea7d70d612345bacbd9624eab63cdf43a585cc3b0d923ed59",["Text"]="-----------------------------------\n-- Trust: Nashmeira II\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.NASHMEIRA)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.LILISETTE_II] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.ARCIELA_II] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.IROHA_II] = xi.trust.messageOffset.TEAMWORK_3,\n        [xi.magic.spell.LION_II] = xi.trust.messageOffset.TEAMWORK_4,\n        [xi.magic.spell.PRISHE_II] = xi.trust.messageOffset.TEAMWORK_5,\n    })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 75 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n    -- TODO: Should only use Curaga when *3* or more party members are below 75%\n    -- Setting the Curaga threshold a bit lower here to prevent a priority conflict with regular Cure gambit, above.\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 50 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURAGA })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.POISON }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.POISONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PARALYSIS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PARALYNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.BLINDNESS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.BLINDNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SILENCE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.SILENA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PETRIFICATION }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.DISEASE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.VIRUNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.CURSE_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURSNA })\n\n    mob:addGambit(ai.t.SELF, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n\n    mob:addListener('WEAPONSKILL_USE', 'NASHMEIRA_II_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == 3243 then -- Imperial Authority\n            -- No! Stand back!\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\n\n    mob:setTrustTPSkillSettings(ai.tp.ASAP, ai.s.RANDOM)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/noillurie.lua"]={["Path"]="scripts/actions/spells/trust/noillurie.lua",["SHA256"]="d6ae0ff5a63fb03deae848125008c9a92e01a930ff4aaef5127655228c7efda0",["Text"]="-----------------------------------\n-- Trust: Noillurie\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/ovjang.lua"]={["Path"]="scripts/actions/spells/trust/ovjang.lua",["SHA256"]="bb1f9d97f0846f16565b80589019e051e3c4f2a3b18024e936b847ea0c87b4bd",["Text"]="-----------------------------------\n-- Trust: Ovjang\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/pieuje_uc.lua"]={["Path"]="scripts/actions/spells/trust/pieuje_uc.lua",["SHA256"]="26cede09bfa6bdca390b5186285d3b182db34a146b0c96755afbb16c7d346a8e",["Text"]="-----------------------------------\n-- Trust: Pieuje UC\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/prishe.lua"]={["Path"]="scripts/actions/spells/trust/prishe.lua",["SHA256"]="7964e47a7f7e766d60314c16f6f48906c29847cf21cd1490fb8f535935f719b9",["Text"]="-----------------------------------\n-- Trust: Prishe\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.PRISHE_II)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.ULMIA] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.CHERUKIKI] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.KUKKI_CHEBUKKI] = xi.trust.messageOffset.TEAMWORK_3,\n        [xi.magic.spell.MAKKI_CHEBUKKI] = xi.trust.messageOffset.TEAMWORK_4,\n        [xi.magic.spell.MILDAURION] = xi.trust.messageOffset.TEAMWORK_5,\n    })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 25 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/prishe_ii.lua"]={["Path"]="scripts/actions/spells/trust/prishe_ii.lua",["SHA256"]="d49942cc6a9ed291ccb08c327e3827c8a6625055dff892dfbf3f5c75520354fb",["Text"]="-----------------------------------\n-- Trust: Prishe II\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.PRISHE)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    local psychoAnima  = 3539\n\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.TENZEN_II   ] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.NASHMEIRA_II] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.LILISETTE_II] = xi.trust.messageOffset.TEAMWORK_3,\n        [xi.magic.spell.ARCIELA_II  ] = xi.trust.messageOffset.TEAMWORK_4,\n        [xi.magic.spell.IROHA_II    ] = xi.trust.messageOffset.TEAMWORK_5,\n    })\n\n    local itemOneGambit = mob:addGambit(ai.t.SELF, { ai.c.HPP_LT, 35 }, { ai.r.MS, ai.s.SPECIFIC, psychoAnima })\n    -- TODO: Add additional logic for Hysteroanima\n    -- local itemTwoGambit = mob:addGambit(ai.t.TARGET, { ai.c.CASTING_MA, 35 }, { ai.r.MS, ai.s.SPECIFIC, 3540 })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 25 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURAGA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURAGA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_II }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURAGA })\n\n    -- TODO: Trust Synergy: If Ulmia in the party, Prishe will cast Curaga when party members are in the yellow instead of red.\n    -- Prishe will use Cure spells exclusively on Ulmia (Only Cure I-IV)\n    -- https://ffxiclopedia.fandom.com/wiki/Trust:_Prishe_II\n\n    mob:addListener('WEAPONSKILL_USE', 'PRISHE_II_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == 3234 then -- Nullifying Dropkick\n            -- Welcome to Painville!\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\n\n    mob:addListener('WEAPONSKILL_STATE_EXIT', 'ANIMA_USED', function(mobArg, skillId, wasExecuted)\n        if skillId == psychoAnima then\n            mobArg:removeGambit(itemOneGambit)\n        end\n\n        --[[\n        if skillId == hysteroAnima then\n            mobArg:removeGambit(itemTwoGambit)\n        end\n        ]]--\n    end)\n\n    mob:setTrustTPSkillSettings(ai.tp.ASAP, ai.s.RANDOM)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/qultada.lua"]={["Path"]="scripts/actions/spells/trust/qultada.lua",["SHA256"]="45f05eb6d3af9b77ff2ba67c233616a78285cb9ed38ca25a3de93e3fcd68e4e9",["Text"]="-----------------------------------\n-- Trust: Qultada\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.CORSAIRS_ROLL }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.CORSAIRS_ROLL })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.CHAOS_ROLL }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.CHAOS_ROLL })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS, 0 }, { ai.r.RATTACK, 0, 0 }, 10)\n\n    -- Notable: Uses a balance of melee and ranged attacks.\n    -- TODO: Observe his WS behavior on retail\n    mob:setTrustTPSkillSettings(ai.tp.OPENER, ai.s.RANDOM)\n\n    -- https://forum.square-enix.com/ffxi/threads/49425-Dec-10-2015-%28JST%29-Version-Update?p=567979&viewfull=1#post567979\n    -- Per the December 10, 2015 update:\n    -- \"The \"Enhanced Magic Accuracy\" attribute has been added.\"\n    local power = mob:getMainLvl() / 5\n    mob:addMod(xi.mod.MACC, power)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/rahal.lua"]={["Path"]="scripts/actions/spells/trust/rahal.lua",["SHA256"]="b629acb1a9514acebb10fbb1f769ad39208a9c642e5bd5766e16e95283f1870d",["Text"]="-----------------------------------\n-- Trust: Rahal\n-- Possesses Dragon Killer.\n-- Rahal is an aggressive tank who uses Berserk.\n-- Prioritizes Flash over Provoke.\n-- Will only cast Cure when a party member is below 33% health and will use the highest tier available.\n-- Will only use Sentinel when he is below 35% health.\n-- He tries to interrupt TP-abilities and high-tier spells with Shield Bash.\n-- Holds up to 2500 TP to close skillchains.\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.TRION] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.CURILLA] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.EXCENMILLE] = xi.trust.messageOffset.TEAMWORK_3,\n        [xi.magic.spell.EXCENMILLE_S] = xi.trust.messageOffset.TEAMWORK_4,\n    })\n\n    -- Dragon Killer handled in mob_pool_mods\n    mob:addMod(xi.mod.ENMITY, 10)\n    mob:addMod(xi.mod.DMG, -500) -- Damage Taken -5%\n    mob:addMod(xi.mod.HPP, 10)\n\n    local lvl = mob:getMainLvl()\n\n    if lvl >= 10 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_HAS_TOP_ENMITY, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PROVOKE })\n    end\n\n    if lvl >= 15 then\n        mob:addGambit(ai.t.TARGET, { ai.l.OR(\n            { ai.c.CASTING_MA, 0 },\n            { ai.c.READYING_JA, 0 },\n            { ai.c.READYING_MS, 0 },\n            { ai.c.READYING_WS, 0 }) }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SHIELD_BASH })\n    end\n\n    if lvl >= 30 then\n        mob:addGambit(ai.t.MASTER, { ai.c.NOT_STATUS, xi.effect.BERSERK }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.BERSERK  })\n        mob:addGambit(ai.t.SELF,   { ai.c.HPP_LT,     35                }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.SENTINEL })\n    end\n\n    mob:addGambit(ai.t.PARTY,  { ai.c.HPP_LT,     33                }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE    })\n    mob:addGambit(ai.t.SELF,   { ai.c.NOT_STATUS, xi.effect.ENLIGHT }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.ENLIGHT })\n    mob:addGambit(ai.t.SELF,   { ai.c.NOT_STATUS, xi.effect.PHALANX }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PHALANX })\n    mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS,     xi.effect.FLASH   }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.FLASH        })\n    mob:addGambit(ai.t.PARTY,  { ai.c.STATUS,     xi.effect.SLEEP_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE         })\n\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.HIGHEST, 2500)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/rainemard.lua"]={["Path"]="scripts/actions/spells/trust/rainemard.lua",["SHA256"]="917dfa3649a70975dc79d55c9d496445a9ec997e795cdd5d377f84c9267145a7",["Text"]="-----------------------------------\n-- Trust: Rainemard\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.CURILLA] = xi.trust.messageOffset.TEAMWORK_1,\n    })\n\n    -- TODO: Selection based on enemy weakness\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.ENFIRE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ENFIRE })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.EVASION_DOWN }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.DISTRACT }, 60)\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.PHALANX }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PHALANX })\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.HASTE }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.HASTE })\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.REFRESH }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.REFRESH })\n\n    -- If Curilla is present, will cast Haste/Phalanx/Refresh on her.\n    mob:addGambit(ai.t.CURILLA, { ai.c.NOT_STATUS, xi.effect.HASTE }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.HASTE })\n    mob:addGambit(ai.t.CURILLA, { ai.c.NOT_STATUS, xi.effect.PHALANX }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PHALANX_II })\n    mob:addGambit(ai.t.CURILLA, { ai.c.NOT_STATUS, xi.effect.REFRESH }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.REFRESH })\n\n    -- NOTE: Do these late, to try and avoid clashing with healers casting -ra's\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.PROTECT }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PROTECT })\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.SHELL }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SHELL })\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/robel-akbel.lua"]={["Path"]="scripts/actions/spells/trust/robel-akbel.lua",["SHA256"]="8878d76ee14807fa90f928e422b84bbd0656fc6d44c6b08f498126a3d8ec13fd",["Text"]="-----------------------------------\n-- Trust: Robel-Akbel\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/romaa_mihgo.lua"]={["Path"]="scripts/actions/spells/trust/romaa_mihgo.lua",["SHA256"]="2a0873e79c2059ee571239f3d4d7d981d91d5d249c69bd64a1da3c482a044965",["Text"]="-----------------------------------\n-- Trust: Romaa Mihgo\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/rongelouts.lua"]={["Path"]="scripts/actions/spells/trust/rongelouts.lua",["SHA256"]="73ca1279492bf7d5de6d999f33210e16b2704be6c9688216965aff1f9c39d59c",["Text"]="-----------------------------------\n-- Trust: Rongelouts\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"}};
